\shortans{-7/48}

\loigiai{
Nhân các phần số và giữ phần biến của đơn thức: $- \dfrac{7 x^{2} y^{8}}{6}\dfrac{x y^{4}}{8} = - \frac{7 x^{3} y^{12}}{48}$, suy ra hệ số là $- \frac{7}{48}$.
}\end{ex}

